    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;

  const r1 = applyVoucher(invoice, { code: 'SUMMER2026', amount: 5000 });
  assert.equal(r1.ok, true);

  const r2 = applyVoucher(r1.value, { code: 'ANOTHER', amount: 2000 });
  assert.deepEqual(r2, { ok: false, error: 'VOUCHER_EXISTS' });
});

test('applyVoucher rejects invalid amount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;

  assert.deepEqual(applyVoucher(invoice, { code: 'BAD', amount: 0 }), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(applyVoucher(invoice, { code: 'BAD', amount: -1000 }), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(applyVoucher(invoice, { code: 'BAD', amount: 100.5 }), { ok: false, error: 'AMOUNT_INVALID' });
});

test('invoiceTotals includes voucher in calculation', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const withVoucher = applyVoucher(invoice, { code: 'SUMMER2026', amount: 5000 }).value;

  const totals = invoiceTotals(withVoucher);
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat - 5000);
});

test('invoiceTotals voucher is 0 without a voucher', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

test('applyVoucher does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;

  const originalVoucher = invoice.voucher;
  applyVoucher(invoice, { code: 'SUMMER2026', amount: 5000 });

  assert.equal(invoice.voucher, originalVoucher);
});

