import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, lineDiscount, lineVat, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-003');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice normalizes customer ID', () => {
  const r1 = createInvoice({
    customerId: 'c-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: '  C-003  ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r1.ok, true);
  assert.equal(r2.ok, true);
  assert.equal(r1.value.customerId, 'C-003');
  assert.equal(r2.value.customerId, 'C-003');
});

test('createInvoice uses NET30 as default terms', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.terms, 'NET30');
  assert.equal(r.value.dueDate, '2026-11-06');
});

test('createInvoice accepts NET14 terms', () => {
  const r = createInvoice({
    customerId: 'C-003',
