test('invoiceTotals with multiple lines and mixed discounts', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21, discountPercent: 20 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 132500);
  assert.equal(totals.discount, 18000);
  const afterDiscount = 132500 - 18000;
